test('makeResult creates correct result structure', () => {
  const miniSearch = new MiniSearch({ fields: ['title'], storeFields: ['category'] });
  miniSearch.add({ id: 1, title: 'test', category: 'fiction' });
  const rawValue = { score: 10, terms: ['test', 'query'], match: { test: ['title'] } };
  const result = miniSearch['makeResult'](0, rawValue);
  expect(result).toMatchObject({
    id: 1,
    score: 20,
    terms: ['test'],
    queryTerms: ['test', 'query'],
    category: 'fiction'
  });
});

test('makeResult handles empty terms array', () => {
  const miniSearch = new MiniSearch({ fields: ['title'] });
  miniSearch.add({ id: 1, title: 'test' });
  const rawValue = { score: 10, terms: [], match: { test: ['title'] } };
  const result = miniSearch['makeResult'](0, rawValue);
  expect(result.score).toBe(10);
  expect(result.queryTerms).toEqual([]);
});

test('executeQuery applies filter at QueryCombination level', () => {
  const miniSearch = new MiniSearch({ fields: ['title'], storeFields: ['category'] });
  miniSearch.add({ id: 1, title: 'motorcycle art', category: 'fiction' });
  miniSearch.add({ id: 2, title: 'abstract art', category: 'history' });
  const results = miniSearch.executeQuery({
    combineWith: 'OR',
    queries: ['art'],
    filter: (result) => result.category === 'fiction'
  }, {});
  expect(results.size).toBe(1);
  expect(results.has(0)).toBe(true);
});

