test('handles nested QueryCombination with filters at multiple levels', () => {
  const miniSearch = new MiniSearch({ fields: ['title'], storeFields: ['category'] });
  miniSearch.add({ id: 1, title: 'art book', category: 'fiction' });
  miniSearch.add({ id: 2, title: 'art history', category: 'history' });
  const results = miniSearch.search({
    combineWith: 'AND',
    queries: [{
      combineWith: 'OR',
      queries: ['art', 'book'],
      filter: (r) => r.category === 'fiction'
    }]
  });
  expect(results).toHaveLength(1);
  expect(results[0].category).toBe('fiction');
});

test('makeResult handles missing stored fields', () => {
  const miniSearch = new MiniSearch({ fields: ['title'] });
  miniSearch.add({ id: 1, title: 'test' });
  const rawValue = { score: 10, terms: ['test'], match: { test: ['title'] } };
  const result = miniSearch['makeResult'](0, rawValue);
  expect(result.id).toBe(1);
  expect(result.score).toBe(10);
});

test('executeQuery filter correctly removes entries from combined Map', () => {
  const miniSearch = new MiniSearch({ fields: ['title'], storeFields: ['score'] });
  miniSearch.add({ id: 1, title: 'test', score: 5 });
  miniSearch.add({ id: 2, title: 'test', score: 3 });
  const results = miniSearch.executeQuery({
    combineWith: 'OR',
    queries: ['test'],
    filter: (r) => r.score > 4
  }, {});
  expect(results.size).toBe(1);
  const remaining = Array.from(results.keys());
  expect(remaining).toContain(0);
  expect(remaining).not.toContain(1);
});

